/**
 * Returns the `classPrefix` option of a theme.
 *
 * Returns `undefined` when the option is not set, or when the installed `@primeuix/styled` cannot
 * prefix its CSS. In development the second case logs a warning once.
 *
 * @param theme The theme, shared or isolated.
 * @returns The prefix, or `undefined`.
 */
export declare function getClassPrefix(theme: {
    getOptions?(): {
        classPrefix?: string;
    } | undefined;
    styleName?(name: string): string;
} | null | undefined): string | undefined;
/**
 * Applies a `classPrefix` to a class value: a string, an array or an object of classes.
 *
 * @param value The class value.
 * @param prefix The `classPrefix`. Without one, or with `p`, the classes are only joined.
 * @returns The class list with `p-` classes renamed.
 */
export declare function prefixClasses(value: unknown, prefix?: string): string;
/**
 * Applies a `classPrefix` to the `.p-` classes in a selector or a piece of CSS.
 *
 * @param selector The selector or CSS.
 * @param prefix The `classPrefix`. Without one, or with `p`, `selector` is returned as is.
 * @returns The selector with `.p-` classes renamed.
 */
export declare function prefixSelector<T extends string | null | undefined>(selector: T, prefix?: string): T;
